import{_ as r,C as n,o as e,c as o,a4 as a,b as d,w as l,a as s,E,a5 as h}from"./chunks/framework.2-Vke5-n.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"sidebarDepth":4,"author":"フューチャー株式会社","layout":"home","hero":{"name":"はじめての非機能要件","tagline":"Non Functional Requirement Guidelines","actions":[{"theme":"brand","text":"第一部 全体プロセス編","link":"./overview.md"},{"theme":"brand","text":"第二部 個別ナレッジ編","link":"./knowledge.md"},{"theme":"alt","text":"Appendix","link":"./appendix.md"}]}},"headers":[],"relativePath":"documents/forNFR/index.md","filePath":"documents/forNFR/index.md"}'),A={name:"documents/forNFR/index.md"};function p(u,t,b,m,f,c){const i=n("Mermaid");return e(),o("div",null,[t[1]||(t[1]=a('<h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p>非機能要件はアーキテクチャを大きく左右するため、抜け落ちや認識齟齬があると大きな手戻りが発生する。そのため、できる限り早期に関係者と合意すべきである。しかし現状、要件定義から合意に至るプロセスは個人の経験に依存しがちで、標準的な手法が確立されていない。</p><p>本ガイドラインでは、この様な状況を改善するため、非機能要件について円滑に合意形成するための手法をまとめる。</p><h3 id="前提" tabindex="-1">前提 <a class="header-anchor" href="#前提" aria-label="Permalink to &quot;前提&quot;">​</a></h3><h4 id="想定読者" tabindex="-1">想定読者 <a class="header-anchor" href="#想定読者" aria-label="Permalink to &quot;想定読者&quot;">​</a></h4><p>本ガイドラインは、非機能要件の定義と合意をリードする立場の担当者を主な対象とする。「はじめての」と題しているが、まったくの初学者向けの入門書ではない。ここでの「はじめて」は非機能要件定義に取り組むのが初めてという意味であり、具体的には次のいずれかに当てはまる人を想定する（いずれも、個別技術の深い知識は前提としない）。</p><ul><li>プロジェクトのライフサイクルを一通り経験し技術的な勘所はついているが、非機能要件定義を担当するのは初めての人</li><li>非機能要件定義を経験頼み・我流で進めてきたが、標準的な型を身につけたい人</li></ul><h4 id="対象とするシステム" tabindex="-1">対象とするシステム <a class="header-anchor" href="#対象とするシステム" aria-label="Permalink to &quot;対象とするシステム&quot;">​</a></h4><p>本ガイドラインが暗黙的に想定するシステム像は、次の通りである。</p><table tabindex="0"><thead><tr><th style="text-align:left;">区分</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;">主な対象</td><td style="text-align:left;">Webアプリケーション（業務システム／Webサービス等）</td></tr><tr><td style="text-align:left;">インフラ形態</td><td style="text-align:left;">クラウド・オンプレミスのいずれも対象とする</td></tr><tr><td style="text-align:left;">主な対象外</td><td style="text-align:left;">組み込み・IoT機器、リアルタイム制御システムなど、Webアプリケーションとは非機能の関心事が大きく異なるシステム（電力制約・時間的確実性・物理制御など）</td></tr></tbody></table><h4 id="本書の構造" tabindex="-1">本書の構造 <a class="header-anchor" href="#本書の構造" aria-label="Permalink to &quot;本書の構造&quot;">​</a></h4><p>本ガイドラインは、最初からすべてを通読する必要はない。読者が直面している課題やプロジェクトのフェーズに合わせて、必要なノウハウへ最短でアクセスできるよう、役割の異なる3部構成とした。</p>',12)),(e(),d(h,null,{default:l(()=>[E(i,{id:"mermaid-80",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%3Cb%3E%E7%AC%AC%E4%B8%80%E9%83%A8%3A%20%E5%85%A8%E4%BD%93%E3%83%97%E3%83%AD%E3%82%BB%E3%82%B9%E7%B7%A8%3C%2Fb%3E%3Cbr%2F%3E5W1H%E3%81%AB%E6%B2%BF%E3%81%A3%E3%81%A6%E8%AA%AC%E6%98%8E%E3%81%99%E3%82%8B%E3%80%82%22%5D%0A%20%20%20%20B%5B%22%3Cb%3E%E7%AC%AC%E4%BA%8C%E9%83%A8%3A%20%E5%80%8B%E5%88%A5%E3%83%8A%E3%83%AC%E3%83%83%E3%82%B8%E7%B7%A8%3C%2Fb%3E%3Cbr%2F%3E%E5%90%84%E5%88%86%E9%87%8E%E3%81%94%E3%81%A8%E3%81%AB%E8%AA%AC%E6%98%8E%E3%81%99%E3%82%8B%E3%80%82%22%5D%0A%20%20%20%20C%5B%22%3Cb%3EAppendix%3A%20%E4%BB%98%E9%8C%B2%3C%2Fb%3E%3Cbr%2F%3E%E4%BB%98%E9%8C%B2%22%5D%0A%0A%20%20%20%20A%20--%3E%20B%20--%3E%20C%0A%0A%20%20%20%20classDef%20default%20text-align%3Aleft%3B%0A"})]),fallback:l(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<ul><li><a href="./overview.html">第一部（全体プロセス編）</a><ul><li>非機能要件を定義し合意するまでの、ドメインに依存しない進め方と思考の型。初めての方はまず通読を推奨する</li></ul></li><li><a href="./knowledge.html">第二部（個別ドメイン・ナレッジ編）</a><ul><li>可用性・性能など、要件ごとの具体的な決め方。必要な項目を辞書的に活用する。</li></ul></li><li><a href="./appendix.html">Appendix</a><ul><li>業界標準フレームワークや用語の正確な定義。裏取りの補助資料として用いる</li></ul></li></ul><h3 id="非機能要件定義と成長" tabindex="-1">非機能要件定義と成長 <a class="header-anchor" href="#非機能要件定義と成長" aria-label="Permalink to &quot;非機能要件定義と成長&quot;">​</a></h3><p>非機能要件定義に本気で向き合う経験は、次のような形で、取り組む人自身を育てる。</p><ul><li><strong>どう作るかから、何を作るべきかへ視座が上がる</strong><br> 非機能要件定義は、どう実現するかではなく、何をなぜ作るべきかを議論し、合意する営みである。言われたものを作る立場から、何を作るべきかを考える立場へ転換できる。</li><li><strong>技術的な深さが問われ、鍛えられる</strong><br> 要件定義とはいえ、どう実現するか（設計）やどれくらいのコストがかかるかのイメージがなければ、深い要件定義はできない。実現可能性を欠いた要件を避けるには一定の技術的専門性が要り、弱い領域があればキャッチアップが求められる。裏を返せば、ここは技術力が試され、鍛えられる場である。</li><li><strong>ビジネスの視点が身につく</strong><br> ビジネスとして達成したいことが、システム要件としてどの項目に落ちるのか。その翻訳を実地で体験することは、技術とビジネスを橋渡しする力を養う。</li><li><strong>合意形成のコミュニケーション力が磨かれる</strong><br> 合意は、自分の都合ではなく相手の言葉に合わせて対話することで生まれる。これはアーキテクトに必須のスキルであり、実践の場となる。</li><li><strong>網羅的に向き合うことで、自分を知る</strong><br> 特定の非機能要件の実現について経験することはあっても、非機能を網羅的に意識する機会は、この要件定義フェーズをおいて他にない。全体を見渡すことで、自分の弱い領域も見えてくる。それは、己を振り返るきっかけにもなる。</li></ul><p>非機能要件定義は、地味で、正解の見えにくい仕事である。しかし、視座・技術・ビジネス・対人・自己認識という専門職の土台が一度に鍛えられる場は、そう多くない。目の前の要件を埋める作業としてではなく、自らの成長の機会として臨んでほしい。</p><h2 id="謝辞" tabindex="-1">謝辞 <a class="header-anchor" href="#謝辞" aria-label="Permalink to &quot;謝辞&quot;">​</a></h2><p>このアーキテクチャガイドラインの作成には多くの方々にご協力いただいた。心より感謝申し上げる。</p><ul><li><strong>作成者</strong>: 真野隼記、武田大輝、清水利博、亀井隆徳、河崎泰子</li><li><strong>レビュアー</strong>: 澁川喜規、宮崎将太</li></ul><div class="next-page-nav"><p>次のページ: <a href="./overview.html">第一部 全体プロセス編</a></p></div>',9))])}const B=r(A,[["render",p]]);export{_ as __pageData,B as default};
